static int kc_voice_stop_and_recognize(void)
{
  char app_id[128];
  char token[256];
  char cluster[128];
  char result[256];
  size_t pcm_len;
  int capture_error;
  int ret;

  pthread_mutex_lock(&g_voice.lock);
  if (g_voice.state != KC_VOICE_RECORDING &&
      g_voice.state != KC_VOICE_STARTING)
    {
      pthread_mutex_unlock(&g_voice.lock);
      return -EINVAL;
    }

  g_voice.capture_running = false;
  pthread_mutex_unlock(&g_voice.lock);

  if (g_voice.capture != NULL)
    {
      audio_capture_abort(g_voice.capture);
    }

  if (g_voice.capture_started)
    {
      pthread_join(g_voice.capture_worker, NULL);
      g_voice.capture_started = false;
    }

  if (g_voice.capture != NULL)
    {
      audio_capture_close(g_voice.capture);
      g_voice.capture = NULL;
    }

  pthread_mutex_lock(&g_voice.lock);
  pcm_len = g_voice.pcm_len;
  capture_error = g_voice.capture_error;
  kc_voice_set_state_locked(KC_VOICE_RECOGNIZING, 0, NULL);
  pthread_mutex_unlock(&g_voice.lock);

  if (pcm_len == 0)
    {
      ret = capture_error < 0 ? capture_error : -ENODATA;
      goto failed;
    }

  ret = kc_voice_load_credentials(app_id, sizeof(app_id),
                                  token, sizeof(token),
                                  cluster, sizeof(cluster));
  if (ret < 0)
    {
      goto failed;
    }

  result[0] = '\0';
  ret = volc_asr_recognize(g_voice.pcm, pcm_len,
                           app_id, token, cluster,
                           result, sizeof(result));
  if (ret < 0 || result[0] == '\0')
    {
      if (ret == 0)
        {
          ret = -ENODATA;
        }
      goto failed;
    }

  free(g_voice.pcm);
  g_voice.pcm = NULL;
  g_voice.pcm_len = 0;

  pthread_mutex_lock(&g_voice.lock);
  kc_voice_set_state_locked(KC_VOICE_RESULT, 0, result);
  pthread_mutex_unlock(&g_voice.lock);
  syslog(LOG_INFO, "KNOWLEDGE_CARDS: ASR result: %s\n", result);
  return 0;

failed:
  free(g_voice.pcm);
  g_voice.pcm = NULL;
  g_voice.pcm_len = 0;

  pthread_mutex_lock(&g_voice.lock);
  kc_voice_set_state_locked(KC_VOICE_ERROR, ret, NULL);
  pthread_mutex_unlock(&g_voice.lock);
  syslog(LOG_ERR, "KNOWLEDGE_CARDS: ASR failed: %d\n", ret);
  return ret;
}

static void *kc_voice_worker(void *arg)
{
  bool start;
  bool stop;

  (void)arg;

  while (true)
    {
      while (sem_wait(&g_voice.command_sem) < 0 && errno == EINTR)
        {
        }

      pthread_mutex_lock(&g_voice.lock);
      start = g_voice.start_pending;
      stop = g_voice.stop_pending;
      g_voice.start_pending = false;
      g_voice.stop_pending = false;
      pthread_mutex_unlock(&g_voice.lock);

      if (start)
        {
          kc_voice_start_capture();
        }

      pthread_mutex_lock(&g_voice.lock);
      stop = stop || g_voice.stop_pending;
      g_voice.stop_pending = false;
      pthread_mutex_unlock(&g_voice.lock);

      if (stop)
        {
          kc_voice_stop_and_recognize();
        }
    }

  return NULL;
}

int kc_voice_init(void)
{
  pthread_attr_t attr;
  int ret;

  pthread_mutex_lock(&g_voice.lock);
  if (g_voice.initialized)
    {
      pthread_mutex_unlock(&g_voice.lock);
      return 0;
    }
  pthread_mutex_unlock(&g_voice.lock);

  config_store_init();
  sem_init(&g_voice.command_sem, 0, 0);

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, KC_VOICE_THREAD_STACK);
  ret = pthread_create(&g_voice.worker, &attr, kc_voice_worker, NULL);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      return -ret;
    }

  pthread_mutex_lock(&g_voice.lock);
  g_voice.initialized = true;
  kc_voice_set_state_locked(kc_voice_is_configured() ? KC_VOICE_IDLE :
                            KC_VOICE_CONFIG_REQUIRED, 0, NULL);
  pthread_mutex_unlock(&g_voice.lock);
  return 0;
}

int kc_voice_start_async(void)
{
  int ret = 0;

  pthread_mutex_lock(&g_voice.lock);
  if (!g_voice.initialized)
    {
      ret = -ENODEV;
    }
  else if (g_voice.state == KC_VOICE_STARTING ||
           g_voice.state == KC_VOICE_RECORDING ||
           g_voice.state == KC_VOICE_RECOGNIZING)
    {
      ret = -EBUSY;
    }
  else
    {
      g_voice.start_pending = true;
      g_voice.stop_pending = false;
      kc_voice_set_state_locked(KC_VOICE_STARTING, 0, NULL);
      sem_post(&g_voice.command_sem);
    }
  pthread_mutex_unlock(&g_voice.lock);
  return ret;
}

int kc_voice_stop_async(void)
{
  int ret = 0;

  pthread_mutex_lock(&g_voice.lock);
  if (!g_voice.initialized)
    {
      ret = -ENODEV;
    }
  else if (g_voice.state != KC_VOICE_STARTING &&
           g_voice.state != KC_VOICE_RECORDING)
    {
      ret = -EINVAL;
    }
  else
    {
      g_voice.stop_pending = true;
      sem_post(&g_voice.command_sem);
    }
  pthread_mutex_unlock(&g_voice.lock);
  return ret;
}

void kc_voice_get_snapshot(struct kc_voice_snapshot_s *snapshot)
{
  if (snapshot == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_voice.lock);
  snapshot->state = g_voice.state;
  snapshot->error = g_voice.error;
  snapshot->generation = g_voice.generation;
  kc_voice_copy(snapshot->text, sizeof(snapshot->text), g_voice.text);
  pthread_mutex_unlock(&g_voice.lock);
}

int kc_voice_configure(const char *app_id, const char *token,
                       const char *cluster)
{
  int ret;

  if (app_id == NULL || app_id[0] == '\0' ||
      token == NULL || token[0] == '\0')
    {
      return -EINVAL;
    }

  config_store_init();
  ret = claw_config_set(AGENT_CFG_KEY_VOLC_APPKEY, app_id);
  if (ret != OK)
    {
      return -EIO;
    }

  ret = claw_config_set(AGENT_CFG_KEY_VOLC_TOKEN, token);
  if (ret != OK)
    {
      return -EIO;
    }

  ret = claw_config_set(AGENT_CFG_KEY_VOLC_ASR_CLUSTER,
                        cluster != NULL && cluster[0] != '\0' ? cluster :
                        AGENT_DOUBAO_ASR_CLUSTER);
  if (ret != OK)
    {
      return -EIO;
    }

  pthread_mutex_lock(&g_voice.lock);
  if (g_voice.initialized &&
      g_voice.state == KC_VOICE_CONFIG_REQUIRED)
    {
      kc_voice_set_state_locked(KC_VOICE_IDLE, 0, NULL);
    }

  syslog(LOG_INFO, "KNOWLEDGE_CARDS: card %u/%u: %s\n",
         (unsigned int)g_card_index + 1, (unsigned int)KC_CARD_COUNT,
         card->title);
}

static void kc_reveal_cb(lv_timer_t *timer)
{
  const char *content = g_csapp_cards[g_card_index].content;
  size_t total = kc_line_count(content);

  if (g_visible_lines < total)
    {
      g_visible_lines++;
      kc_set_visible_lines(content, g_visible_lines);
    }

  if (g_visible_lines >= total)
    {
      lv_label_set_text(g_state_label, "已展开");
      lv_timer_pause(timer);
    }
}

static void kc_next(void)
{
  g_card_index = (g_card_index + 1) % KC_CARD_COUNT;
  kc_show_card();
}

static void kc_previous(void)
{
  g_card_index = (g_card_index + KC_CARD_COUNT - 1) % KC_CARD_COUNT;
  kc_show_card();
}

static void kc_next_event(lv_event_t *event)
{
  if (lv_event_get_code(event) == LV_EVENT_CLICKED)
    {
      kc_next();
    }
}

static void kc_previous_event(lv_event_t *event)
{
  if (lv_event_get_code(event) == LV_EVENT_CLICKED)
    {
      kc_previous();
    }
}

static bool kc_topic_is_csapp(const char *topic)
{
  char normalized[64];
  size_t output = 0;

  if (strstr(topic, "计算机系统") != NULL ||
      strstr(topic, "深入理解计算机系统") != NULL)
    {
      return true;
    }

  while (*topic != '\0' && output < sizeof(normalized) - 1)
    {
      char ch = *topic++;

      if (ch >= 'a' && ch <= 'z')
        {
          ch = (char)(ch - 'a' + 'A');
        }

      if ((ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9'))
        {
          normalized[output++] = ch;
        }
    }

  normalized[output] = '\0';
  return strstr(normalized, "CSAPP") != NULL;
}

static void kc_set_mic_color(uint32_t color)
{
  if (g_mic_button != NULL)
    {
      lv_obj_set_style_bg_color(g_mic_button, lv_color_hex(color), 0);
    }
}

static void kc_voice_poll_cb(lv_timer_t *timer)
{
  struct kc_voice_snapshot_s snapshot;

  (void)timer;
  kc_voice_get_snapshot(&snapshot);
  if (snapshot.generation == g_voice_generation)
    {
      return;
    }

  g_voice_generation = snapshot.generation;
  switch (snapshot.state)
    {
      case KC_VOICE_CONFIG_REQUIRED:
        lv_label_set_text(g_state_label, "请配置语音服务");
        kc_set_mic_color(0x57615d);
        break;

      case KC_VOICE_IDLE:
        lv_label_set_text(g_state_label, "按住说出学习主题");
        kc_set_mic_color(0x2c7a62);
        break;

      case KC_VOICE_STARTING:
        lv_label_set_text(g_state_label, "正在打开麦克风");
        kc_set_mic_color(0xb7791f);
        break;

      case KC_VOICE_RECORDING:
        lv_label_set_text(g_state_label, "正在聆听，松开识别");
        kc_set_mic_color(0xc2413b);
        break;

      case KC_VOICE_RECOGNIZING:
        lv_label_set_text(g_state_label, "正在识别");
        kc_set_mic_color(0xb7791f);
        break;

      case KC_VOICE_RESULT:
        lv_label_set_text_fmt(g_topic_label, "语音主题 / %s", snapshot.text);
        kc_set_mic_color(0x2c7a62);
        if (kc_topic_is_csapp(snapshot.text))
          {
            g_card_index = 0;
            kc_show_card();
            lv_label_set_text(g_state_label, "识别成功");
          }
        else
          {
            lv_label_set_text(g_state_label, "该主题尚未缓存");
          }
        break;

      case KC_VOICE_ERROR:
        if (snapshot.error == -ENODATA)
          {
            lv_label_set_text(g_state_label, "没有听清，请重试");
          }
        else if (snapshot.error == -ENODEV)
          {
            lv_label_set_text(g_state_label, "麦克风不可用");
          }
        else
          {
            lv_label_set_text(g_state_label, "识别失败，请重试");
          }
        kc_set_mic_color(0x8f3b36);
        break;

      default:
        break;
    }
}

static void kc_mic_event(lv_event_t *event)
{
  lv_event_code_t code = lv_event_get_code(event);
  int ret;

  if (code == LV_EVENT_PRESSED)
    {
      if (g_reveal_timer != NULL)
        {
          lv_timer_pause(g_reveal_timer);
        }

      ret = kc_voice_start_async();
      if (ret < 0 && ret != -EBUSY)
        {
          lv_label_set_text(g_state_label, "语音服务未就绪");
        }
    }
  else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST)
    {
      ret = kc_voice_stop_async();
      if (ret < 0 && ret != -EINVAL)
        {
          lv_label_set_text(g_state_label, "无法结束录音");
        }
    }
}

static void kc_card_event(lv_event_t *event)
{
  lv_event_code_t code = lv_event_get_code(event);

  if (code == LV_EVENT_CLICKED)
    {
      const char *content = g_csapp_cards[g_card_index].content;

      g_visible_lines = kc_line_count(content);
      kc_set_visible_lines(content, g_visible_lines);
      lv_label_set_text(g_state_label, "已展开");
      lv_timer_pause(g_reveal_timer);
    }
  else if (code == LV_EVENT_GESTURE)
    {
      lv_dir_t direction = lv_indev_get_gesture_dir(lv_indev_get_act());

      if (direction == LV_DIR_LEFT)
        {
          kc_next();
        }
      else if (direction == LV_DIR_RIGHT)
        {
          kc_previous();
        }
    }
}

